import axios from "axios";

const API = "http://localhost:8080";

// ✅ GET LOGGED USER
export const fetchLoggedUser = async () => {
  return await axios.get(`${API}/auth/user`);
};

// ✅ GET USER REPOS
export const fetchUserRepos = async () => {
  return await axios.get(`${API}/auth/repos`);
};

// ✅ FETCH PR DATA (MODE FROM URL)
export const fetchPRData = async (payload, mode) => {
  return await axios.post(`${API}/api/pr/${mode}`, payload);
};
